321		// Seed a document through the existing endpoint.
322		for i := 0; i < 3; i++ {
323			w, _ := postJSON(t, h, "/v1/documents/doc1/changes", map[string]any{
324				"deviceId": "dev-1",
325				"changes":  []any{map[string]any{"id": fmt.Sprintf("c%d", i), "payload": map[string]any{"i": i}}},
326			})
327			if w.Code != http.StatusOK {
328				t.Fatal(w.Body.String())
329			}
330		}
331	
332		// Full list: same shape and values as the document endpoint.
333		w, body := doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/doc1/changes")
334		if w.Code != http.StatusOK {
335			t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
336		}
