353			t.Fatalf("paged = %v next=%v", list, body["nextCursor"])
354		}
355	
356		// Unknown document through a live session: empty list, nextCursor 0 — the
357		// existing semantics, not a 404.
358		w, body = doRequest(t, h, http.MethodGet, "/v1/sessions/sess/documents/ghost/changes")
359		if w.Code != http.StatusOK || len(body["changes"].([]any)) != 0 || body["nextCursor"].(float64) != 0 {
360			t.Fatalf("unknown doc = %d %v", w.Code, body)
361		}
