470		if err != nil {
471			t.Fatal(err)
472		}
473		t.Cleanup(func() { _ = s2.Close() })
474		h2 := NewHandler(s2)
475	
476		// Replay is idempotent and the session-scoped read still works.
477		w, body := postJSON(t, h2, "/v1/devices/dev-1/sessions", map[string]any{"sessionId": "sess"})
478		if w.Code != http.StatusOK || body["created"] != false {
